/* 2mm.c: this file is part of PolyBench/C */

#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "2mm.h"

/* Tunable blocking factors for the 2mm kernel.
   They can be overridden at compile time, e.g.:
     -DT2MM_J_BLOCK=128 -DT2MM_L_BLOCK=128

   Choose values appropriate for the target cache hierarchy.
   Both must be strictly positive. */
#ifndef T2MM_J_BLOCK
# define T2MM_J_BLOCK 64
#endif

#ifndef T2MM_L_BLOCK
# define T2MM_L_BLOCK 64
#endif


/* Array initialization. */
static
void init_array(int ni, int nj, int nk, int nl,
		DATA_TYPE *alpha,
		DATA_TYPE *beta,
		DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj),
		DATA_TYPE POLYBENCH_2D(C,NJ,NL,nj,nl),
		DATA_TYPE POLYBENCH_2D(D,NI,NL,ni,nl))
{
  int i, j;

  *alpha = 1.5;
  *beta = 1.2;
  for (i = 0; i < ni; i++)
    for (j = 0; j < nk; j++)
      A[i][j] = (DATA_TYPE) ((i*j+1) % ni) / ni;
  for (i = 0; i < nk; i++)
    for (j = 0; j < nj; j++)
      B[i][j] = (DATA_TYPE) (i*(j+1) % nj) / nj;
  for (i = 0; i < nj; i++)
    for (j = 0; j < nl; j++)
      C[i][j] = (DATA_TYPE) ((i*(j+3)+1) % nl) / nl;
  for (i = 0; i < ni; i++)
    for (j = 0; j < nl; j++)
      D[i][j] = (DATA_TYPE) (i*(j+2) % nk) / nk;
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int ni, int nl,
		 DATA_TYPE POLYBENCH_2D(D,NI,NL,ni,nl))
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("D");
  for (i = 0; i < ni; i++)
    for (j = 0; j < nl; j++) {
	if ((i * ni + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, D[i][j]);
    }
  POLYBENCH_DUMP_END("D");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static void __attribute__((flatten, noinline))
kernel_2mm(int ni, int nj, int nk, int nl,
	   DATA_TYPE alpha,
	   DATA_TYPE beta,
	   DATA_TYPE POLYBENCH_2D(tmp,NI,NJ,ni,nj),
	   DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
	   DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj),
	   DATA_TYPE POLYBENCH_2D(C,NJ,NL,nj,nl),
	   DATA_TYPE POLYBENCH_2D(D,NI,NL,ni,nl))
{
  int i, j, k;

  /* Local, restrict-qualified aliases to help the compiler
     optimize memory accesses and enable vectorization. The
     second dimension uses the run-time sizes so that the
     compiler knows the exact row stride. */
  DATA_TYPE (*restrict tmp_)[nj] = tmp;
  DATA_TYPE (*restrict A_)[nk]   = A;
  DATA_TYPE (*restrict B_)[nj]   = B;
  DATA_TYPE (*restrict C_)[nl]   = C;
  DATA_TYPE (*restrict D_)[nl]   = D;

  /* Use the PolyBench-provided loop bounds (which may differ
     from ni/nj/nk/nl when benchmarking reduced problems). */
  const int ni_ = _PB_NI;
  const int nj_ = _PB_NJ;
  const int nk_ = _PB_NK;
  const int nl_ = _PB_NL;

#pragma scop
  /* D := alpha*A*B*C + beta*D
   *
   * Optimizations vs. the original kernel:
   *  - Separate initialization of tmp from its accumulation.
   *  - Reorder loops to (i,k,j) for both matrix products so that
   *    the inner loops walk contiguous memory in B, C, tmp, and D.
   *  - Introduce simple blocking on the j / l dimensions with
   *    tunable block sizes (T2MM_J_BLOCK and T2MM_L_BLOCK) to
   *    improve cache locality when matrices are large.
   *  - Keep the order of accumulation in the reduction dimension
   *    (k) identical for each element to preserve numerical
   *    behavior as much as possible.
   */

  /* 1) Initialize tmp to zero. */
  for (i = 0; i < ni_; ++i)
    for (j = 0; j < nj_; ++j)
      tmp_[i][j] = SCALAR_VAL(0.0);

  /* 2) tmp = alpha * A * B
   *    Loop order: i (rows of A/tmp), k (shared dimension), j (columns).
   *    For a fixed (i,k), we traverse contiguous slices of B[k][*] and
   *    tmp[i][*], which is cache-friendly and vectorizable. */
  for (i = 0; i < ni_; ++i)
  {
    for (k = 0; k < nk_; ++k)
    {
      DATA_TYPE a_ik = alpha * A_[i][k];

      /* Block the j dimension to keep working sets for B[k][j] and
         tmp[i][j] inside the upper cache levels. */
      int jb;
      for (jb = 0; jb < nj_; jb += T2MM_J_BLOCK)
      {
        int j_end = jb + T2MM_J_BLOCK;
        if (j_end > nj_)
          j_end = nj_;

        for (j = jb; j < j_end; ++j)
          tmp_[i][j] += a_ik * B_[k][j];
      }
    }
  }

  /* 3) Scale D by beta (independent of tmp and C). Splitting this
   *    from the accumulation step below exposes a simple, fully
   *    vectorizable loop to the compiler without changing the
   *    per-element operation order. */
  for (i = 0; i < ni_; ++i)
    for (j = 0; j < nl_; ++j)
      D_[i][j] *= beta;

  /* 4) D += tmp * C
   *    Dimensions: tmp (ni x nj), C (nj x nl), D (ni x nl).
   *    Loop order: i (rows of tmp/D), k (shared dimension), j (columns).
   *    For each (i,k), tmp[i][k] is reused across an entire row of
   *    C[k][*] and D[i][*]. */
  for (i = 0; i < ni_; ++i)
  {
    for (k = 0; k < nj_; ++k)
    {
      DATA_TYPE t_ik = tmp_[i][k];

      int lb;
      for (lb = 0; lb < nl_; lb += T2MM_L_BLOCK)
      {
        int l_end = lb + T2MM_L_BLOCK;
        if (l_end > nl_)
          l_end = nl_;

        for (j = lb; j < l_end; ++j)
          D_[i][j] += t_ik * C_[k][j];
      }
    }
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int ni = NI;
  int nj = NJ;
  int nk = NK;
  int nl = NL;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(tmp,DATA_TYPE,NI,NJ,ni,nj);
  POLYBENCH_2D_ARRAY_DECL(A,DATA_TYPE,NI,NK,ni,nk);
  POLYBENCH_2D_ARRAY_DECL(B,DATA_TYPE,NK,NJ,nk,nj);
  POLYBENCH_2D_ARRAY_DECL(C,DATA_TYPE,NJ,NL,nj,nl);
  POLYBENCH_2D_ARRAY_DECL(D,DATA_TYPE,NI,NL,ni,nl);

  /* Initialize array(s). */
  init_array (ni, nj, nk, nl, &alpha, &beta,
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(B),
	      POLYBENCH_ARRAY(C),
	      POLYBENCH_ARRAY(D));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_2mm (ni, nj, nk, nl,
	      alpha, beta,
	      POLYBENCH_ARRAY(tmp),
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(B),
	      POLYBENCH_ARRAY(C),
	      POLYBENCH_ARRAY(D));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(ni, nl,  POLYBENCH_ARRAY(D)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(tmp);
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);
  POLYBENCH_FREE_ARRAY(C);
  POLYBENCH_FREE_ARRAY(D);

  return 0;
}

