   *
   *    This is kept in a separate loop to preserve the exact evaluation
   *    order: first D is scaled once, then contributions from tmp * C
   *    are accumulated in k order, as in the original code.
   * -------------------------------------------------------------------- */
  for (i = 0; i < _PB_NI; i++)
    for (j = 0; j < _PB_NL; j++)
      D[i][j] *= beta;

  /* --------------------------------------------------------------------
   * 4. D += tmp * C
   *
   *    Loop order: i (rows of D/tmp) - k (shared dim) - j (cols of D/C).
   *    Inner-most loop walks unit-stride through:
   *      - C[k][j] (row of C)
   *      - D[i][j] (row of D)
   *
   *    As above, for every fixed (i,j), k increases from 0 to nj-1
   *    in the same order as in the original code.
   * -------------------------------------------------------------------- */
  for (ii = 0; ii < _PB_NI; ii += T2MM_BLOCK_I)
  {
    int i_end = ii + T2MM_BLOCK_I;
    if (i_end > _PB_NI)
      i_end = _PB_NI;

    for (kk = 0; kk < _PB_NJ; kk += T2MM_BLOCK_K)
    {
      int k_end = kk + T2MM_BLOCK_K;
      if (k_end > _PB_NJ)
        k_end = _PB_NJ;

      for (jj = 0; jj < _PB_NL; jj += T2MM_BLOCK_L)
      {
        int j_end = jj + T2MM_BLOCK_L;
        if (j_end > _PB_NL)
          j_end = _PB_NL;

        for (i = ii; i < i_end; ++i)
          for (k = kk; k < k_end; ++k)
          {
            DATA_TYPE r = tmp[i][k];

#pragma GCC ivdep
            for (j = jj; j < j_end; ++j)
              D[i][j] += r * C[k][j];
          }
      }
    }
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int ni = NI;
  int nj = NJ;
  int nk = NK;
  int nl = NL;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(tmp,DATA_TYPE,NI,NJ,ni,nj);
  POLYBENCH_2D_ARRAY_DECL(A,DATA_TYPE,NI,NK,ni,nk);
  POLYBENCH_2D_ARRAY_DECL(B,DATA_TYPE,NK,NJ,nk,nj);
  POLYBENCH_2D_ARRAY_DECL(C,DATA_TYPE,NJ,NL,nj,nl);
  POLYBENCH_2D_ARRAY_DECL(D,DATA_TYPE,NI,NL,ni,nl);

  /* Initialize array(s). */
  init_array (ni, nj, nk, nl, &alpha, &beta,
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(B),
	      POLYBENCH_ARRAY(C),
	      POLYBENCH_ARRAY(D));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_2mm (ni, nj, nk, nl,
	      alpha, beta,
	      POLYBENCH_ARRAY(tmp),
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(B),
	      POLYBENCH_ARRAY(C),
	      POLYBENCH_ARRAY(D));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(ni, nl,  POLYBENCH_ARRAY(D)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(tmp);
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);
  POLYBENCH_FREE_ARRAY(C);
  POLYBENCH_FREE_ARRAY(D);

  return 0;
}
